import{_ as a,o as t,c as n,ag as i}from"./chunks/framework.BJFNwp4n.js";const u=JSON.parse('{"title":"Maltese Reading and Word-by-Word Practice","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/index.md","filePath":"en/more/maltese/practice/index.md"}'),r={name:"en/more/maltese/practice/index.md"};function s(o,e,d,l,c,m){return t(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794416186000"},[...e[0]||(e[0]=[i('<h1 id="maltese-reading-and-word-by-word-practice" tabindex="-1">Maltese Reading and Word-by-Word Practice <a class="header-anchor" href="#maltese-reading-and-word-by-word-practice" aria-label="Permalink to &quot;Maltese Reading and Word-by-Word Practice&quot;">​</a></h1><p>This folder contains the requirements and two categories of beginner reading material: dialogues and emails. Each exercise presents the complete Maltese text first, followed by an English sentence-by-sentence translation and word notes. Each category has its own index and numbering sequence. Hyphens and apostrophes are often part of Maltese spelling; the notes explain articles, preposition contractions, and person suffixes where useful.</p><h2 id="document-1-requirements" tabindex="-1">Document 1: Requirements <a class="header-anchor" href="#document-1-requirements" aria-label="Permalink to &quot;Document 1: Requirements&quot;">​</a></h2><ol><li><a href="./00-requirements.html">Maltese Practice Document Requirements</a>: scope and formatting requirements for this practice set.</li></ol><h2 id="dialogues" tabindex="-1">Dialogues <a class="header-anchor" href="#dialogues" aria-label="Permalink to &quot;Dialogues&quot;">​</a></h2><p><a href="./dialogues/">Dialogue Index</a>: eight dialogues, numbered from 01 within this category.</p><h2 id="emails" tabindex="-1">Emails <a class="header-anchor" href="#emails" aria-label="Permalink to &quot;Emails&quot;">​</a></h2><p><a href="./emails/">Email Index</a>: seventeen emails, numbered from 01 within this category.</p><h2 id="reading-tips" tabindex="-1">Reading Tips <a class="header-anchor" href="#reading-tips" aria-label="Permalink to &quot;Reading Tips&quot;">​</a></h2><ul><li>Read the complete Maltese text first and try to understand it before consulting the sentence translations and word notes.</li><li>Word meanings depend on context; pronoun suffixes, articles, and contracted prepositions do not always map directly onto separate English words.</li><li>A Maltese word may have different meanings in different contexts. Use the subject and sentence meaning to interpret unfamiliar verb forms.</li></ul>',10)])])}const p=a(r,[["render",s]]);export{u as __pageData,p as default};
